 * the outermost array.
 *
 * @param json the JSON document to read
 * @return a {@link JsonReader} positioned after {@code beginArray()}
 * @throws IOException if an I/O error occurs while creating the reader
 */
private JsonReader setupReaderAndBeginArray(String json) throws IOException {
  JsonReader reader = new JsonReader(reader(json));
  reader.beginArray();
  return reader;
}

