@Test
public void testStrictUnnecessaryArraySeparatorsWithSkipValue_ValidFirstElement() throws IOException {
  JsonReader reader = setupReaderAndBeginArray("[true,,true]");
  assertThat(reader.nextBoolean()).isTrue();

  MalformedJsonException e = assertThrows(
      "skipValue should throw MalformedJsonException for missing element after first true",
      MalformedJsonException.class,
      () -> reader.skipValue());

  assertStrictError(e, "line 1 column 8 path $[1]");
}

