  StringWriter stringWriter = new StringWriter();
  JsonWriter jsonWriter = new JsonWriter(stringWriter);
  jsonWriter.beginArray();
  for (float v : values) {
    jsonWriter.value(v);
  }
  jsonWriter.endArray();
  jsonWriter.close();
  return stringWriter.toString();
}

// Edge‑case float values
@Test
public void testFloats_EdgeValues() throws IOException {
  String actualJson = setupTestFloats(-0.0f, Float.MAX_VALUE, Float.MIN_VALUE, 0.0f);
  assertThat(actualJson)
      .isEqualTo("[-0.0,3.4028235E38,1.4E-45,0.0]");
}

// Typical float values
@Test
public void testFloats_TypicalValues() throws IOException {
  String actualJson = setupTestFloats(1.0f, -0.5f, 2.2250739E-38f, 3.723379f);
  assertThat(actualJson)
      .isEqualTo("[1.0,-0.5,2.2250739E-38,3.723379]");
}

// Mathematical‑constant float values
@Test
public void testFloats_MathConstants() throws IOException {
  String actualJson = setupTestFloats((float) Math.PI, (float) Math.E);
  assertThat(actualJson)
      .isEqualTo("[3.1415927,2.7182817]");
}

