/**
 * Helper that creates a {@link JsonReader} positioned at the start of the object for the
 * invalid‑JSON test case.
 */
private static JsonReader createReaderForInvalidJson() throws IOException {
    String json =
        "{\n"
            + "   \"h\\ello\": true,\n"
            + "   \"foo\": [\"world\"]\n"
            + "}";
    JsonReader reader = new JsonReader(reader(json));
    reader.beginObject();
    return reader;
}

/**
 * Executes {@code reader.nextName()} and returns the {@link MalformedJsonException}
 * that is expected to be thrown. If no exception is thrown, an {@link AssertionError}
 * is raised to fail the test.
 */
private static MalformedJsonException getMalformedJsonException(JsonReader reader) {
    try {
        reader.nextName();
        throw new AssertionError("Expected MalformedJsonException was not thrown");
    } catch (MalformedJsonException e) {
        return e;
    } catch (IOException e) {
        throw new RuntimeException(e);
    }
}

/**
