@Test
public void testSet() {
  JsonArray a = new JsonArray();
  a.add(1);

  List<JsonElement> list = a.asList();
  JsonElement old = list.set(0, new JsonPrimitive(2));
  assertThat(old).isEqualTo(new JsonPrimitive(1));
  assertThat(list.get(0)).isEqualTo(new JsonPrimitive(2));
  assertThat(a.get(0)).isEqualTo(new JsonPrimitive(2));

  assertThrows(IndexOutOfBoundsException.class, () -> list.set(-1, new JsonPrimitive(1)));
  assertThrows(IndexOutOfBoundsException.class, () -> list.set(2, new JsonPrimitive(1)));

  NullPointerException e = assertThrows(NullPointerException.class, () -> list.set(0, null));
  assertThat(e).hasMessageThat().isEqualTo("Element must be non-null");
}

proposals.refactored:
private static final int ONE = 1;
private static final int TWO = 2;
private static final int NEGATIVE_ONE = -1;

@Test
public void testSet() {
    JsonArray a = new JsonArray();
    a.add(ONE);

    List<JsonElement> list = a.asList();
    JsonElement old = list.set(0, new JsonPrimitive(TWO));
    assertWithMessage("The element returned by set should be the original value ONE")
        .that(old).isEqualTo(new JsonPrimitive(ONE));
    assertWithMessage("After set, list.get(0) should reflect the new value TWO")
        .that(list.get(0)).isEqualTo(new JsonPrimitive(TWO));
    assertWithMessage("After set, underlying JsonArray get(0) should reflect the new value TWO")
        .that(a.get(0)).isEqualTo(new JsonPrimitive(TWO));

    assertThrows("Setting element at negative index should throw IndexOutOfBoundsException",
        IndexOutOfBoundsException.class,
        () -> list.set(NEGATIVE_ONE, new JsonPrimitive(ONE)));
    assertThrows("Setting element beyond size should throw IndexOutOfBoundsException",
        IndexOutOfBoundsException.class,
        () -> list.set(TWO, new JsonPrimitive(ONE)));

    NullPointerException e = assertThrows("Setting null element should throw NullPointerException",
        NullPointerException.class,
        () -> list.set(0, null));
    assertWithMessage("NullPointerException should have message 'Element must be non-null'")
        .that(e).hasMessageThat().isEqualTo("Element must be non-null");
}

