public void testNumbers() throws IOException {
    String actualJson = writeNumbersArray();
    assertThat(actualJson)
        .isEqualTo("[0,9223372036854775808,-9223372036854775809,3.141592653589793238462643383]");
}

/** Helper that writes the full set of numbers to a JSON array and returns the resulting string. */
private String writeNumbersArray() throws IOException {
    StringWriter stringWriter = new StringWriter();
    JsonWriter jsonWriter = new JsonWriter(stringWriter);
    jsonWriter.beginArray();
    jsonWriter.value(BigInteger.ZERO);
    jsonWriter.value(new BigInteger("9223372036854775808"));
    jsonWriter.value(new BigInteger("-9223372036854775809"));
    jsonWriter.value(new BigDecimal("3.141592653589793238462643383"));
    jsonWriter.endArray();
    jsonWriter.close();
    return stringWriter.toString();
}

