public void testReadAcrossBuffers() throws IOException {
    String json = buildJsonAcrossBuffers();
    JsonReader reader = createLenientReader(json);
    JsonToken token = reader.peek();
    assertThat(token).isEqualTo(JsonToken.NUMBER);
}

/**
 * Builds the JSON string that spans across the internal buffer boundary.
 * Starts with '#', followed by spaces to fill {@code JsonReader.BUFFER_SIZE - 3},
 * then the suffix {@code "\n)]}'\n3"}.
 */
private static String buildJsonAcrossBuffers() {
    StringBuilder sb = new StringBuilder("#");
    for (int i = 0; i < JsonReader.BUFFER_SIZE - 3; i++) {
        sb.append(' ');
    }
    sb.append("\n)]}'\n3");
    return sb.toString();
}

/**
 * Creates a {@link JsonReader} for the given JSON string with lenient strictness.
 */
private static JsonReader createLenientReader(String json) throws IOException {
    JsonReader reader = new JsonReader(reader(json));
    reader.setStrictness(Strictness.LENIENT);
    return reader;
}

