/** Helper that creates a JsonReader positioned at the start of the array. */
private JsonReader createReaderForMixedCaseLiterals() throws IOException {
  JsonReader reader = new JsonReader(reader("[True,TruE,False,FALSE,NULL,nulL]"));
  reader.beginArray();
  return reader;
}

/** Verifies that boolean literals are parsed correctly, regardless of case. */
@Test
public void testMixedCaseLiterals_BooleanLiterals() throws IOException {
  JsonReader reader = createReaderForMixedCaseLiterals();

  assertThat(reader.nextBoolean()).isTrue();   // "True"
  assertThat(reader.nextBoolean()).isTrue();   // "TruE"
  assertThat(reader.nextBoolean()).isFalse();  // "False"
  assertThat(reader.nextBoolean()).isFalse();  // "FALSE"
}

/** Verifies that null literals are parsed correctly, regardless of case. */
@Test
public void testMixedCaseLiterals_NullLiterals() throws IOException {
  JsonReader reader = createReaderForMixedCaseLiterals();

  // Skip the four boolean literals first.
  reader.nextBoolean();
  reader.nextBoolean();
  reader.nextBoolean();
  reader.nextBoolean();

  // Now read the null literals.
  reader.nextNull(); // "NULL"
  reader.nextNull(); // "nulL"

  // After the nulls the next token should be END_ARRAY.
  assertThat(reader.peek()).isEqualTo(JsonToken.END_ARRAY);
}

/** Verifies that the reader reaches END_DOCUMENT after processing the array. */
@Test
public void testMixedCaseLiterals_EndOfDocument() throws IOException {
  JsonReader reader = createReaderForMixedCaseLiterals();

  // Consume all literals.
  reader.nextBoolean(); // "True"
  reader.nextBoolean(); // "TruE"
  reader.nextBoolean(); // "False"
  reader.nextBoolean(); // "FALSE"
  reader.nextNull();    // "NULL"
  reader.nextNull();    // "nulL"

  // End the array and verify the document is finished.
  reader.endArray();
  assertThat(reader.peek()).isEqualTo(JsonToken.END_DOCUMENT);
}

