@Test
public void testNewsHomepage(@TempDir File tempDir) throws IOException {
    File in = getFile("/htmltests/news-com-au-home.html");
    assertTrue("Input HTML file must exist before parsing", in.exists() && !in.isDirectory());

    Document doc = Jsoup.parse(in, "UTF-8", "http://www.news.com.au/");
    assertEquals("Document title should match expected value",
            "News.com.au | News from Australia and around the world online | NewsComAu", doc.title());
    assertEquals("Headline text should be correct",
            "Brace yourself for Metro meltdown", doc.select(".id1225817868581 h4").text().trim());

    Element a = doc.select("a[href=/entertainment/horoscopes]").first();
    assertEquals("Link href attribute should be '/entertainment/horoscopes'",
            "/entertainment/horoscopes", a.attr("href"));
    assertEquals("Absolute href should resolve correctly",
            "http://www.news.com.au/entertainment/horoscopes", a.attr("abs:href"));

    Element hs = doc.select("a[href*=naughty-corners-are-a-bad-idea]").first();
    assertEquals("External link href should match expected URL",
            "http://www.heraldsun.com.au/news/naughty-corners-are-a-bad-idea-for-kids/story-e6frf7jo-1225817899003",
            hs.attr("href"));
    assertEquals("Absolute href should equal href for external link",
            hs.attr("href"), hs.attr("abs:href"));
}

