proposals.original:
    @Test public void testKeepsPreTextAtDepth() {
        String h = "<pre><code><span><b>code

code</b></span></code></pre>";
        Document doc = Jsoup.parse(h);
        assertEquals("code

code", doc.text());
        assertEquals("<pre><code><span><b>code

code</b></span></code></pre>", doc.body().html());
    }

proposals.refactored:
private Document setupTestKeepsPreTextAtDepth() {
    String h = "<pre><code><span><b>code\n\ncode</b></span></code></pre>";
    return Jsoup.parse(h);
}

@Test
public void testKeepsPreTextAtDepth_TextRetention() {
    Document doc = setupTestKeepsPreTextAtDepth();
    assertEquals("Document text should preserve the original line breaks",
                 "code\n\ncode", doc.text());
}

@Test
public void testKeepsPreTextAtDepth_HtmlPreservation() {
    Document doc = setupTestKeepsPreTextAtDepth();
    assertEquals("HTML output should remain exactly as the input after parsing",
                 "<pre><code><span><b>code\n\ncode</b></span></code></pre>", doc.body().html());
}

